#include <stdio.h>
#include <stddef.h>

extern size_t ZSTD_compress(void* dst, size_t dstCapacity, const void* src, size_t srcSize, int compressionLevel);
extern size_t ZSTD_decompress(void* dst, size_t dstCapacity, const void* src, size_t compressedSize);
extern unsigned long long ZSTD_findDecompressedSize(const void *src, size_t srcSize);
extern size_t ZSTD_isError(size_t code);
extern const char* ZSTD_getErrorName(size_t code);

int main() {
    char src[] = "Hello ZSTD Link Test!";
    char compressed[100];
    char decompressed[100];

    size_t cSize = ZSTD_compress(compressed, sizeof(compressed), src, sizeof(src), 3);
    if (ZSTD_isError(cSize)) {
        printf("Compress error: %s\n", ZSTD_getErrorName(cSize));
        return 1;
    }
    printf("Compressed size: %zu\n", cSize);

    size_t dSize = ZSTD_decompress(decompressed, sizeof(decompressed), compressed, cSize);
    if (ZSTD_isError(dSize)) {
        printf("Decompress error: %s\n", ZSTD_getErrorName(dSize));
        return 1;
    }
    printf("Decompressed: %s\n", decompressed);
    return 0;
}
EOF
