{"command":"cat << 'EOF' > /tmp/zstd_test/test_zstd_api.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct ZSTD_CCtx_s ZSTD_CCtx;
typedef struct ZSTD_DCtx_s ZSTD_DCtx;

typedef struct ZSTD_inBuffer_s {
    const void* src;
    size_t size;
    size_t pos;
} ZSTD_inBuffer;

typedef struct ZSTD_outBuffer_s {
    void* dst;
    size_t size;
    size_t pos;
} ZSTD_outBuffer;

typedef enum {
    ZSTD_e_continue = 0,
    ZSTD_e_flush = 1,
    ZSTD_e_end = 2
} ZSTD_EndDirective;

typedef enum {
    ZSTD_c_compressionLevel = 100,
    ZSTD_c_checksumFlag = 201,
    ZSTD_c_nbWorkers = 400
} ZSTD_cParameter;

extern ZSTD_CCtx* ZSTD_createCCtx(void);
extern size_t ZSTD_freeCCtx(ZSTD_CCtx* cctx);
extern ZSTD_DCtx* ZSTD_createDCtx(void);
extern size_t ZSTD_freeDCtx(ZSTD_DCtx* dctx);

extern size_t ZSTD_compressStream2(ZSTD_CCtx* cctx, ZSTD_outBuffer* output, ZSTD_inBuffer* input, ZSTD_EndDirective endOp);
extern size_t ZSTD_decompressStream(ZSTD_DCtx* dctx, ZSTD_outBuffer* output, ZSTD_inBuffer* input);
extern size_t ZSTD_CCtx_setParameter(ZSTD_CCtx* cctx, ZSTD_cParameter param, int value);
extern size_t ZSTD_CCtx_loadDictionary(ZSTD_CCtx* cctx, const void* dict, size_t dictSize);
extern size_t ZSTD_DCtx_loadDictionary(ZSTD_DCtx* dctx, const void* dict, size_t dictSize);

extern unsigned long long ZSTD_getFrameContentSize(const void *src, size_t srcSize);
extern size_t ZSTD_isError(size_t code);
extern const char* ZSTD_getErrorName(size_t code);

extern size_t ZDICT_trainFromBuffer(void* dictBuffer, size_t dictBufferCapacity,
                                   const void* samplesBuffer, const size_t* samplesSizes, unsigned nbSamples);

int main() {
    ZSTD_CCtx* cctx = ZSTD_createCCtx();
    if (!cctx) {
        printf("Failed to create CCtx\n");
        return 1;
    }
    ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, 3);

    char src[] = "Hello ZSTD Streaming Test Data!!!";
    char dst[1024];

    ZSTD_inBuffer in = { src, strlen(src), 0 };
    ZSTD_outBuffer out = { dst, sizeof(dst), 0 };

    size_t res = ZSTD_compressStream2(cctx, &out, &in, ZSTD_e_end);
    if (ZSTD_isError(res)) {
        printf("CompressStream error: %s\n", ZSTD_getErrorName(res));
        ZSTD_freeCCtx(cctx);
        return 1;
    }
    printf("Compressed %zu bytes into %zu bytes\n", strlen(src), out.pos);

    ZSTD_DCtx* dctx = ZSTD_createDCtx();
    char decomp[1024];
    ZSTD_inBuffer din = { dst, out.pos, 0 };
    ZSTD_outBuffer dout = { decomp, sizeof(decomp), 0 };

    res = ZSTD_decompressStream(dctx, &dout, &din);
    if (ZSTD_isError(res)) {
        printf("DecompressStream error: %s\n", ZSTD_getErrorName(res));
    } else {
        decomp[dout.pos] = '\0';
        printf("Decompressed (%zu bytes): %s\n", dout.pos, decomp);
    }

    ZSTD_freeCCtx(cctx);
    ZSTD_freeDCtx(dctx);
    return 0;
}
EOF
