    unsigned char out[1024];
    strm.next_in = (Bytef*)data;
    strm.avail_in = len;
    strm.next_out = out;
    strm.avail_out = sizeof(out);

    deflate(&strm, Z_FINISH);
    size_t comp_len = strm.total_out;
    deflateEnd(&strm);

