    char dec[1024];
    dstrm.next_in = out;
    dstrm.avail_in = comp_len;
    dstrm.next_out = (Bytef*)dec;
    dstrm.avail_out = sizeof(dec);
    inflate(&dstrm, Z_FINISH);
    size_t dec_len = dstrm.total_out;
    inflateEnd(&dstrm);

    dec[dec_len] = '\0';
    printf("Gzip compressed %zu -> %zu, decompressed: %s\n", len, comp_len, dec);
    return 0;
}

