    lzma_code(&strm, LZMA_FINISH);
    size_t comp_len = strm.total_out;
    lzma_end(&strm);

    // Decompress
    lzma_stream dstrm = LZMA_STREAM_INIT;
    if (lzma_auto_decoder(&dstrm, UINT64_MAX, 0) != LZMA_OK) return -1;
    char dec[1024];
    dstrm.next_in = out;
    dstrm.avail_in = comp_len;
    dstrm.next_out = (uint8_t*)dec;
    dstrm.avail_out = sizeof(dec);
    lzma_code(&dstrm, LZMA_FINISH);
    size_t dec_len = dstrm.total_out;
    lzma_end(&dstrm);

    dec[dec_len] = '\0';
    printf("XZ compressed %zu -> %zu, decompressed: %s\n", len, comp_len, dec);
    return 0;
}

int main() {
    char data[] = "Testing gzip and xz streaming in C!";
    test_gzip(data, strlen(data));
    test_xz(data, strlen(data));
