{"command":"cat << 'EOF' > src/utils.c
#include "zstd_cli.h"

void format_size(char* buf, size_t buf_sz, uint64_t bytes) {
    if (bytes < 1024) {
        snprintf(buf, buf_sz, "%6llu   B", (unsigned long long)bytes);
    } else if (bytes < 1024 * 10) {
        snprintf(buf, buf_sz, "%6.2f KiB", (double)bytes / 1024.0);
    } else if (bytes < 1024 * 100) {
        snprintf(buf, buf_sz, "%6.1f KiB", (double)bytes / 1024.0);
    } else if (bytes < 1024 * 1024) {
        snprintf(buf, buf_sz, "%6.0f KiB", (double)bytes / 1024.0);
    } else if (bytes < 1024 * 1024 * 10) {
        snprintf(buf, buf_sz, "%6.2f MiB", (double)bytes / (1024.0 * 1024.0));
    } else if (bytes < 1024 * 1024 * 100) {
        snprintf(buf, buf_sz, "%6.1f MiB", (double)bytes / (1024.0 * 1024.0));
    } else if (bytes < 1024 * 1024 * 1024) {
        snprintf(buf, buf_sz, "%6.0f MiB", (double)bytes / (1024.0 * 1024.0));
    } else if (bytes < 1024ULL * 1024ULL * 1024ULL * 10ULL) {
        snprintf(buf, buf_sz, "%6.2f GiB", (double)bytes / (1024.0 * 1024.0 * 1024.0));
    } else if (bytes < 1024ULL * 1024ULL * 1024ULL * 100ULL) {
        snprintf(buf, buf_sz, "%6.1f GiB", (double)bytes / (1024.0 * 1024.0 * 1024.0));
    } else {
        snprintf(buf, buf_sz, "%6.0f GiB", (double)bytes / (1024.0 * 1024.0 * 1024.0));
    }
}

char* path_basename(const char* path) {
    const char* p = strrchr(path, '/');
    return p ? (char*)(p + 1) : (char*)path;
}

char* path_dirname(const char* path) {
    static char buf[4096];
    snprintf(buf, sizeof(buf), "%s", path);
    return dirname(buf);
}

int is_directory(const char* path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return S_ISDIR(st.st_mode);
    }
    return 0;
}

int is_regular_file(const char* path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return S_ISREG(st.st_mode);
    }
    return 0;
}

uint64_t get_file_size(const char* path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return st.st_size;
    }
    return 0;
}

void add_input_file(Options* opts, const char* filename) {
    if (opts->num_inputs >= opts->cap_inputs) {
        opts->cap_inputs = opts->cap_inputs ? opts->cap_inputs * 2 : 16;
        opts->inputs = realloc(opts->inputs, opts->cap_inputs * sizeof(char*));
    }
    opts->inputs[opts->num_inputs++] = strdup(filename);
}

void collect_files_from_list(Options* opts, const char* list_filename) {
    FILE* f = NULL;
    if (strcmp(list_filename, "-") == 0) {
        f = stdin;
    } else {
        f = fopen(list_filename, "r");
        if (!f) {
            fprintf(stderr, "zstd: can't open %s : %s -- ignored\n", list_filename, strerror(errno));
            return;
        }
    }

    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        size_t len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[--len] = '\0';
        }
        if (len > 0) {
            add_input_file(opts, line);
        }
    }

    if (f != stdin) {
        fclose(f);
    }
}

void collect_files_from_dir(Options* opts, const char* dir_path) {
    DIR* d = opendir(dir_path);
    if (!d) {
        fprintf(stderr, "zstd: can't open directory %s : %s -- ignored \n", dir_path, strerror(errno));
        return;
    }

    struct dirent* entry;
    char path_buf[4096];
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        snprintf(path_buf, sizeof(path_buf), "%s/%s", dir_path, entry->d_name);
        if (is_directory(path_buf)) {
            collect_files_from_dir(opts, path_buf);
        } else {
            add_input_file(opts, path_buf);
        }
    }
    closedir(d);
}
EOF"}

