void print_version(FILE* f, const Options* opts) {
    if (opts->is_zstdcat) {
        fprintf(f, "1.6.0\n");
    } else {
        fprintf(f, "*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n");
    }
}

void options_init(Options* opts, const char* argv0) {
    memset(opts, 0, sizeof(Options));
    opts->program_name = argv0;
    opts->base_program_name = path_basename(argv0);

    opts->mode = MODE_COMPRESS;
    opts->format = FMT_ZSTD;
    opts->compression_level = 3;
    opts->fast_level = 0;
    opts->ultra = 0;
    opts->force = 0;
    opts->keep = 1;
    opts->rm_source = 0;
    opts->stdout_mode = 0;
    opts->verbose = 0;
    opts->quiet = 0;
    opts->recursive = 0;
    opts->checksum = 1;
    opts->threads = 4;
    opts->pass_through = 0;
    opts->sparse = 1;
    opts->long_window = 0;
    opts->rsyncable = 0;
    opts->job_size = 0;
    opts->max_dict_size = 112640;
    opts->bench_level_start = 3;
    opts->bench_level_end = 1;
    opts->bench_time_s = 3;

    if (strcmp(opts->base_program_name, "unzstd") == 0) {
        opts->mode = MODE_DECOMPRESS;
    } else if (strcmp(opts->base_program_name, "zstdcat") == 0 || strcmp(opts->base_program_name, "zcat") == 0) {
        opts->mode = MODE_DECOMPRESS;
        opts->stdout_mode = 1;
        opts->is_zstdcat = 1;
    } else if (strcmp(opts->base_program_name, "zstdmt") == 0) {
        opts->threads = 0;
    }
}

void options_free(Options* opts) {
    if (opts->output_file) free(opts->output_file);
    if (opts->dict_file) free(opts->dict_file);
    if (opts->filelist) free(opts->filelist);
    if (opts->output_dir_flat) free(opts->output_dir_flat);
    if (opts->output_dir_mirror) free(opts->output_dir_mirror);
    for (size_t i = 0; i < opts->num_inputs; i++) {
        free(opts->inputs[i]);
    }
    if (opts->inputs) free(opts->inputs);
}

int options_parse(Options* opts, int argc, char** argv) {
    int pos_stop = 0;

    for (int i = 1; i < argc; i++) {
        const char* arg = argv[i];

        if (pos_stop) {
            add_input_file(opts, arg);
            continue;
        }

        if (strcmp(arg, "--") == 0) {
            pos_stop = 1;
            continue;
        }

        if (arg[0] == '-' && arg[1] != '\0') {
            if (arg[1] == '-') {
                /* Long option */
                if (strcmp(arg, "--decompress") == 0 || strcmp(arg, "--uncompress") == 0) {
                    opts->mode = MODE_DECOMPRESS;
                } else if (strcmp(arg, "--force") == 0) {
                    opts->force = 1;
                } else if (strcmp(arg, "--keep") == 0) {
                    opts->keep = 1;
                } else if (strcmp(arg, "--rm") == 0) {
                    opts->rm_source = 1;
                    opts->keep = 0;
                } else if (strcmp(arg, "--stdout") == 0) {
                    opts->stdout_mode = 1;
                } else if (strcmp(arg, "--verbose") == 0) {
                    opts->verbose++;
                } else if (strcmp(arg, "--quiet") == 0) {
                    opts->quiet++;
                } else if (strcmp(arg, "--version") == 0) {
                    print_version(stdout, opts);
                    exit(0);
                } else if (strcmp(arg, "--help") == 0) {
                    print_long_help(stdout, opts->base_program_name);
                    exit(0);
                } else if (strcmp(arg, "--ultra") == 0) {
                    opts->ultra = 1;
                } else if (strcmp(arg, "--fast") == 0) {
                    opts->fast_level = 1;
                    opts->compression_level = -1;
                } else if (strncmp(arg, "--fast=", 7) == 0) {
                    opts->fast_level = atoi(arg + 7);
                    opts->compression_level = -opts->fast_level;
                } else if (strcmp(arg, "--test") == 0) {
                    opts->mode = MODE_TEST;
                } else if (strcmp(arg, "--train") == 0) {
                    opts->mode = MODE_TRAIN;
                } else if (strncmp(arg, "--train-cover", 13) == 0 || strncmp(arg, "--train-fastcover", 17) == 0 || strncmp(arg, "--train-legacy", 14) == 0) {
                    opts->mode = MODE_TRAIN;
                } else if (strncmp(arg, "--format=", 9) == 0) {
                    const char* fmt = arg + 9;
                    if (strcmp(fmt, "zstd") == 0) opts->format = FMT_ZSTD;
                    else if (strcmp(fmt, "gzip") == 0) opts->format = FMT_GZIP;
                    else if (strcmp(fmt, "xz") == 0) opts->format = FMT_XZ;
                    else if (strcmp(fmt, "lzma") == 0) opts->format = FMT_LZMA;
                    else {
                        fprintf(stderr, "Incorrect parameter: %s \n", arg);
                        print_short_help(stderr, opts->base_program_name);
                        return 1;
                    }
                } else if (strcmp(arg, "--pass-through") == 0 || strcmp(arg, "--no-pass-through") == 0) {
                    opts->pass_through = (strcmp(arg, "--pass-through") == 0);
                } else if (strcmp(arg, "--sparse") == 0 || strcmp(arg, "--no-sparse") == 0) {
                    opts->sparse = (strcmp(arg, "--sparse") == 0);
                } else if (strcmp(arg, "--check") == 0 || strcmp(arg, "--no-check") == 0) {
                    opts->checksum = (strcmp(arg, "--check") == 0);
                } else if (strcmp(arg, "--progress") == 0 || strcmp(arg, "--no-progress") == 0) {
                    /* ignore progress override */
                } else if (strcmp(arg, "--asyncio") == 0 || strcmp(arg, "--no-asyncio") == 0) {
                    /* ignore asyncio override */
                } else if (strcmp(arg, "--rsyncable") == 0) {
                    opts->rsyncable = 1;
                } else if (strncmp(arg, "--long", 6) == 0) {
                    opts->long_window = 27;
                } else if (strncmp(arg, "--filelist=", 11) == 0) {
                    opts->filelist = strdup(arg + 11);
                } else if (strcmp(arg, "--filelist") == 0) {
                    if (i + 1 < argc && argv[i + 1][0] != '-') {
                        opts->filelist = strdup(argv[++i]);
                    } else {
                        fprintf(stderr, "error: command cannot be separated from its argument by another command \n");
                        return 1;
                    }
                } else if (strncmp(arg, "--output-dir-flat=", 18) == 0) {
                    opts->output_dir_flat = strdup(arg + 18);
                } else if (strcmp(arg, "--output-dir-flat") == 0) {
                    if (i + 1 < argc && argv[i + 1][0] != '-') {
                        opts->output_dir_flat = strdup(argv[++i]);
                    } else {
                        fprintf(stderr, "error: command cannot be separated from its argument by another command \n");
                        return 1;
                    }
                } else if (strncmp(arg, "--output-dir-mirror=", 20) == 0) {
                    opts->output_dir_mirror = strdup(arg + 20);
                } else if (strcmp(arg, "--output-dir-mirror") == 0) {
                    if (i + 1 < argc && argv[i + 1][0] != '-') {
                        opts->output_dir_mirror = strdup(argv[++i]);
                    } else {
                        fprintf(stderr, "error: command cannot be separated from its argument by another command \n");
                        return 1;
                    }
                } else if (strncmp(arg, "--maxdict=", 10) == 0) {
                    opts->max_dict_size = atol(arg + 10);
                } else if (strncmp(arg, "--dictID=", 9) == 0) {
                    opts->dict_id = atoi(arg + 9);
                } else if (strncmp(arg, "--trace", 7) == 0 || strncmp(arg, "--patch-", 8) == 0 ||
                           strncmp(arg, "--jobsize", 9) == 0 || strncmp(arg, "--auto-threads", 14) == 0 ||
                           strncmp(arg, "--single-thread", 15) == 0 || strncmp(arg, "--exclude-compressed", 20) == 0 ||
                           strncmp(arg, "--stream-size", 13) == 0 || strncmp(arg, "--size-hint", 11) == 0 ||
                           strncmp(arg, "--target-compressed-block-size", 29) == 0 || strncmp(arg, "--no-dictID", 11) == 0 ||
                           strncmp(arg, "--compress-literals", 19) == 0 || strncmp(arg, "--no-compress-literals", 22) == 0 ||
                           strncmp(arg, "--row-match-finder", 18) == 0 || strncmp(arg, "--no-row-match-finder", 21) == 0 ||
                           strncmp(arg, "--mmap-dict", 11) == 0 || strncmp(arg, "--no-mmap-dict", 14) == 0 ||
                           strncmp(arg, "--split", 7) == 0 || strncmp(arg, "--priority", 10) == 0 ||
                           strncmp(arg, "--adapt", 7) == 0) {
                    /* Accepted advanced options */
                } else {
                    fprintf(stderr, "Incorrect parameter: %s \n", arg);
                    print_short_help(stderr, opts->base_program_name);
                    return 1;
                }
            } else {
                /* Short options bundle */
                size_t len = strlen(arg);
                for (size_t j = 1; j < len; j++) {
                    char c = arg[j];
                    if (c >= '0' && c <= '9') {
                        int lvl = atoi(arg + j);
                        opts->compression_level = lvl;
                        break;
                    } else if (c == 'd') {
                        opts->mode = MODE_DECOMPRESS;
                    } else if (c == 'f') {
                        opts->force = 1;
                    } else if (c == 'k') {
                        opts->keep = 1;
                    } else if (c == 'c') {
                        opts->stdout_mode = 1;
                    } else if (c == 'v') {
                        opts->verbose++;
                    } else if (c == 'q') {
                        opts->quiet++;
                    } else if (c == 'h') {
                        print_short_help(stdout, opts->base_program_name);
                        exit(0);
                    } else if (c == 'H') {
                        print_long_help(stdout, opts->base_program_name);
                        exit(0);
                    } else if (c == 'V') {
                        print_version(stdout, opts);
                        exit(0);
                    } else if (c == 'r') {
                        opts->recursive = 1;
                    } else if (c == 't') {
                        opts->mode = MODE_TEST;
                    } else if (c == 'l') {
                        opts->mode = MODE_LIST;
                    } else if (c == 'S') {
                        /* benchmark single result */
                    } else if (c == 'o') {
                        if (j + 1 < len) {
                            /* e.g. -ofilename - NOT supported in zstd CLI, gives error */
                            fprintf(stderr, "error: command cannot be separated from its argument by another command \n");
                            return 1;
                        } else if (i + 1 < argc && argv[i + 1][0] != '-') {
                            opts->output_file = strdup(argv[++i]);
                        } else {
                            fprintf(stderr, "error: command cannot be separated from its argument by another command \n");
                            return 1;
                        }
                    } else if (c == 'D') {
                        if (j + 1 < len) {
                            /* e.g. -Ddictfile - NOT supported if starting with '/' or unknown */
                            fprintf(stderr, "Incorrect parameter: -%c \n", arg[j+1]);
                            print_short_help(stderr, opts->base_program_name);
                            return 1;
                        } else if (i + 1 < argc && argv[i + 1][0] != '-') {
                            opts->dict_file = strdup(argv[++i]);
                        } else {
                            fprintf(stderr, "error: command cannot be separated from its argument by another command \n");
                            return 1;
                        }
                    } else if (c == 'T') {
                        if (j + 1 < len) {
                            opts->threads = atoi(arg + j + 1);
                        } else if (i + 1 < argc && argv[i + 1][0] != '-') {
                            opts->threads = atoi(argv[++i]);
                        }
                        break;
                    } else if (c == 'b') {
                        opts->mode = MODE_BENCHMARK;
                        if (j + 1 < len) {
                            opts->bench_level_start = atoi(arg + j + 1);
                        }
                        break;
                    } else if (c == 'e') {
                        if (j + 1 < len) {
                            opts->bench_level_end = atoi(arg + j + 1);
                        }
                        break;
                    } else if (c == 'i') {
                        if (j + 1 < len) {
                            opts->bench_time_s = atoi(arg + j + 1);
                        }
                        break;
                    } else if (c == 'M') {
                        break;
                    } else {
                        fprintf(stderr, "Incorrect parameter: -%c \n", c);
                        print_short_help(stderr, opts->base_program_name);
                        return 1;
                    }
                }
            }
        } else {
            add_input_file(opts, arg);
        }
    }

    if (opts->filelist) {
        collect_files_from_list(opts, opts->filelist);
    }

    return 0;
}
EOF"}

