                        break;
                    } else if (c == 'M') {
                        break;
                    } else {
                        fprintf(stderr, "Incorrect parameter: -%c \n", c);
                        print_short_help(stderr, opts->base_program_name);
                        return 1;
                    }
                }
            }
        } else {
            add_input_file(opts, arg);
        }
    }

    if (opts->filelist) {
        collect_files_from_list(opts, opts->filelist);
    }

    return 0;
}
