{"command":"cat << 'EOF' > src/compress.c
#include "zstd_cli.h"
#include <zlib.h>
#include <lzma.h>

static int compress_file_zstd(Options* opts, FILE* fin, FILE* fout, uint64_t* in_bytes_out, uint64_t* out_bytes_out) {
    ZSTD_CCtx* cctx = ZSTD_createCCtx();
    if (!cctx) return 1;

    int level = opts->compression_level;
    if (level > 19 && !opts->ultra) level = 19;

    ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, level);
    if (opts->checksum) ZSTD_CCtx_setParameter(cctx, ZSTD_c_checksumFlag, 1);
    if (opts->threads > 0) ZSTD_CCtx_setParameter(cctx, ZSTD_c_nbWorkers, opts->threads);
    if (opts->rsyncable) ZSTD_CCtx_setParameter(cctx, ZSTD_c_rsyncable, 1);
    if (opts->long_window) ZSTD_CCtx_setParameter(cctx, ZSTD_c_enableLongDistanceMatching, 1);

    if (opts->dict_file) {
        FILE* fdict = fopen(opts->dict_file, "rb");
        if (fdict) {
            fseek(fdict, 0, SEEK_END);
            long dsize = ftell(fdict);
            fseek(fdict, 0, SEEK_SET);
            if (dsize > 0) {
                void* dbuf = malloc(dsize);
                if (dbuf && fread(dbuf, 1, dsize, fdict) == (size_t)dsize) {
                    ZSTD_CCtx_loadDictionary(cctx, dbuf, dsize);
                }
                free(dbuf);
            }
            fclose(fdict);
        }
    }

    size_t in_buf_size = 128 * 1024;
    size_t out_buf_size = 128 * 1024;
    void* in_buf = malloc(in_buf_size);
    void* out_buf = malloc(out_buf_size);

    uint64_t total_in = 0;
    uint64_t total_out = 0;
    int error = 0;

    for (;;) {
        size_t read_bytes = fread(in_buf, 1, in_buf_size, fin);
        total_in += read_bytes;
        int is_last = (read_bytes < in_buf_size);

        ZSTD_inBuffer input = { in_buf, read_bytes, 0 };
        for (;;) {
            ZSTD_outBuffer output = { out_buf, out_buf_size, 0 };
            size_t ret = ZSTD_compressStream2(cctx, &output, &input, is_last ? ZSTD_e_end : ZSTD_e_continue);
            if (ZSTD_isError(ret)) {
                error = 1;
                break;
            }
            if (output.pos > 0) {
                fwrite(out_buf, 1, output.pos, fout);
                total_out += output.pos;
            }
            if (input.pos >= input.size && ret == 0) break;
            if (input.pos >= input.size && !is_last) break;
        }

        if (is_last || error) break;
    }

    free(in_buf);
    free(out_buf);
    ZSTD_freeCCtx(cctx);

    *in_bytes_out = total_in;
    *out_bytes_out = total_out;
    return error;
}

static int compress_file_gzip(Options* opts, FILE* fin, FILE* fout, uint64_t* in_bytes_out, uint64_t* out_bytes_out) {
    (void)opts;
    z_stream strm = {0};
    if (deflateInit2(&strm, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 15 + 16, 8, Z_DEFAULT_STRATEGY) != Z_OK) {
        return 1;
    }

    unsigned char in_buf[64 * 1024];
    unsigned char out_buf[64 * 1024];

    uint64_t total_in = 0;
    uint64_t total_out = 0;
    int error = 0;

    for (;;) {
        size_t read_bytes = fread(in_buf, 1, sizeof(in_buf), fin);
        total_in += read_bytes;
        int flush = (read_bytes < sizeof(in_buf)) ? Z_FINISH : Z_NO_FLUSH;

        strm.next_in = in_buf;
        strm.avail_in = read_bytes;

        do {
            strm.next_out = out_buf;
            strm.avail_out = sizeof(out_buf);
            int ret = deflate(&strm, flush);
            if (ret == Z_STREAM_ERROR) {
                error = 1;
                break;
            }
            size_t have = sizeof(out_buf) - strm.avail_out;
            if (have > 0) {
                fwrite(out_buf, 1, have, fout);
                total_out += have;
            }
        } while (strm.avail_out == 0);

        if (flush == Z_FINISH || error) break;
    }

    deflateEnd(&strm);
    *in_bytes_out = total_in;
    *out_bytes_out = total_out;
    return error;
}

static int compress_file_xz(Options* opts, FILE* fin, FILE* fout, int format_type, uint64_t* in_bytes_out, uint64_t* out_bytes_out) {
    (void)opts;
    lzma_stream strm = LZMA_STREAM_INIT;
    lzma_ret ret_init;
    if (format_type == FMT_LZMA) {
        lzma_options_lzma lzma_opts;
        lzma_lzma_preset(&lzma_opts, LZMA_PRESET_DEFAULT);
        ret_init = lzma_alone_encoder(&strm, &lzma_opts);
    } else {
        ret_init = lzma_easy_encoder(&strm, 6, LZMA_CHECK_CRC64);
    }
    if (ret_init != LZMA_OK) return 1;

    uint8_t in_buf[64 * 1024];
    uint8_t out_buf[64 * 1024];

    uint64_t total_in = 0;
    uint64_t total_out = 0;
    int error = 0;

    for (;;) {
        size_t read_bytes = fread(in_buf, 1, sizeof(in_buf), fin);
        total_in += read_bytes;
        lzma_action action = (read_bytes < sizeof(in_buf)) ? LZMA_FINISH : LZMA_RUN;

        strm.next_in = in_buf;
        strm.avail_in = read_bytes;

        do {
            strm.next_out = out_buf;
            strm.avail_out = sizeof(out_buf);
            lzma_ret ret = lzma_code(&strm, action);
            if (ret != LZMA_OK && ret != LZMA_STREAM_END) {
                error = 1;
                break;
            }
            size_t have = sizeof(out_buf) - strm.avail_out;
            if (have > 0) {
                fwrite(out_buf, 1, have, fout);
                total_out += have;
            }
        } while (strm.avail_out == 0);

        if (action == LZMA_FINISH || error) break;
    }

    lzma_end(&strm);
    *in_bytes_out = total_in;
    *out_bytes_out = total_out;
    return error;
}

static void make_parent_dirs(const char* path) {
    char temp[4096];
    snprintf(temp, sizeof(temp), "%s", path);
    char* dir = dirname(temp);
    if (dir && strcmp(dir, ".") != 0 && strcmp(dir, "/") != 0) {
        struct stat st;
        if (stat(dir, &st) != 0) {
            make_parent_dirs(dir);
            mkdir(dir, 0755);
        }
    }
}

int process_compress(Options* opts) {
    if (opts->compression_level > 19 && !opts->ultra) {
        fprintf(stderr, "Warning : compression level higher than max, reduced to 19 \n");
    }

    /* Check terminal stdin if no input files */
    if (opts->num_inputs == 0) {
        if (isatty(STDIN_FILENO) && !opts->force) {
            fprintf(stderr, "stdin is a console, aborting\n");
            return 1;
        }
        add_input_file(opts, "-");
    }

    /* Check output to stdout console */
    int writing_to_stdout = opts->stdout_mode ||
                           (opts->output_file && strcmp(opts->output_file, "-") == 0) ||
                           (opts->num_inputs == 1 && strcmp(opts->inputs[0], "-") == 0 && !opts->output_file);

    if (writing_to_stdout && isatty(STDOUT_FILENO) && !opts->stdout_mode && !opts->force) {
        fprintf(stderr, "stdout is a console, aborting\n");
        return 1;
    }

    /* Multi-file concatenated output to -o */
    if (opts->num_inputs > 1 && opts->output_file && strcmp(opts->output_file, "-") != 0) {
        fprintf(stderr, "zstd: WARNING: all input files will be processed and concatenated into a single output file: %s \n"
                        "The concatenated output CANNOT regenerate original file names nor directory structure. \n", opts->output_file);
    }

    uint64_t grand_total_in = 0;
    uint64_t grand_total_out = 0;
    size_t successful_files = 0;
    int has_error = 0;

    FILE* concat_fout = NULL;
    if (opts->num_inputs > 1 && opts->output_file && strcmp(opts->output_file, "-") != 0) {
        concat_fout = fopen(opts->output_file, "wb");
        if (!concat_fout) {
            fprintf(stderr, "zstd: can't open %s : %s -- ignored \n", opts->output_file, strerror(errno));
            return 1;
        }
    }

    for (size_t i = 0; i < opts->num_inputs; i++) {
        const char* in_path = opts->inputs[i];

        if (strcmp(in_path, "-") != 0 && is_directory(in_path)) {
            if (opts->recursive) {
                collect_files_from_dir(opts, in_path);
                continue;
            } else {
                fprintf(stderr, "zstd: %s is a directory -- ignored \n", in_path);
                has_error = 1;
                continue;
            }
        }

        FILE* fin = NULL;
        if (strcmp(in_path, "-") == 0) {
            fin = stdin;
        } else {
            fin = fopen(in_path, "rb");
            if (!fin) {
                if (errno == ENOENT) {
                    fprintf(stderr, "zstd: can't stat %s : No such file or directory -- ignored \n", in_path);
                } else {
                    fprintf(stderr, "zstd: %s: %s \n", in_path, strerror(errno));
                }
                has_error = 1;
                continue;
            }
        }

        char out_path[4096];
        int write_stdout = 0;

        if (opts->stdout_mode || (strcmp(in_path, "-") == 0 && !opts->output_file)) {
            write_stdout = 1;
            snprintf(out_path, sizeof(out_path), "stdout");
        } else if (concat_fout) {
            snprintf(out_path, sizeof(out_path), "%s", opts->output_file);
        } else if (opts->output_file && opts->num_inputs == 1) {
            snprintf(out_path, sizeof(out_path), "%s", opts->output_file);
        } else {
            const char* ext = ".zst";
            if (opts->format == FMT_GZIP) ext = ".gz";
            else if (opts->format == FMT_XZ) ext = ".xz";
            else if (opts->format == FMT_LZMA) ext = ".lzma";

            if (opts->output_dir_flat) {
                snprintf(out_path, sizeof(out_path), "%s/%s%s", opts->output_dir_flat, path_basename(in_path), ext);
            } else if (opts->output_dir_mirror) {
                snprintf(out_path, sizeof(out_path), "%s/%s%s", opts->output_dir_mirror, in_path, ext);
            } else {
                snprintf(out_path, sizeof(out_path), "%s%s", in_path, ext);
            }
        }

        FILE* fout = NULL;
        if (write_stdout) {
            fout = stdout;
        } else if (concat_fout) {
            fout = concat_fout;
        } else {
            if (!opts->force && stat(out_path, NULL) == 0) {
                fprintf(stderr, "zstd: %s already exists; overwrite (y/n) ? Not overwritten \n", out_path);
                if (fin != stdin) fclose(fin);
                has_error = 1;
                continue;
            }
            make_parent_dirs(out_path);
            fout = fopen(out_path, "wb");
            if (!fout) {
                fprintf(stderr, "zstd: %s: %s \n", out_path, strerror(errno));
                if (fin != stdin) fclose(fin);
                has_error = 1;
                continue;
            }
        }

        uint64_t in_bytes = 0, out_bytes = 0;
        int comp_err = 0;

        if (opts->format == FMT_ZSTD) {
            comp_err = compress_file_zstd(opts, fin, fout, &in_bytes, &out_bytes);
        } else if (opts->format == FMT_GZIP) {
            comp_err = compress_file_gzip(opts, fin, fout, &in_bytes, &out_bytes);
        } else if (opts->format == FMT_XZ || opts->format == FMT_LZMA) {
            comp_err = compress_file_xz(opts, fin, fout, opts->format, &in_bytes, &out_bytes);
        }

        if (fin != stdin) fclose(fin);
        if (fout != stdout && !concat_fout) fclose(fout);

        if (comp_err) {
            has_error = 1;
            if (!write_stdout && !concat_fout) unlink(out_path);
        } else {
            successful_files++;
            grand_total_in += in_bytes;
            grand_total_out += out_bytes;

            if (opts->rm_source && strcmp(in_path, "-") != 0 && !write_stdout) {
                unlink(in_path);
            }

            if (!opts->quiet && opts->num_inputs == 1 && !opts->stdout_mode && strcmp(in_path, "-") != 0) {
                char src_sz[32], dst_sz[32];
                format_size(src_sz, sizeof(src_sz), in_bytes);
                format_size(dst_sz, sizeof(dst_sz), out_bytes);
                double pct = (double)out_bytes * 100.0 / (in_bytes ? in_bytes : 1);
                fprintf(stderr, "%s :%6.2f%%   ( %s => %s, %s) \n", in_path, pct, src_sz, dst_sz, out_path);
            }
        }
    }

    if (concat_fout) fclose(concat_fout);

    if (!opts->quiet && opts->num_inputs > 1) {
        char src_sz[32], dst_sz[32];
        format_size(src_sz, sizeof(src_sz), grand_total_in);
        format_size(dst_sz, sizeof(dst_sz), grand_total_out);
        double pct = (double)grand_total_out * 100.0 / (grand_total_in ? grand_total_in : 1);
        fprintf(stderr, "  %zu files compressed :%6.2f%% ( %s => %s) \n", successful_files, pct, src_sz, dst_sz);
    }

    return has_error ? 1 : 0;
}
EOF"}

