static int derive_decompressed_filename(const char* in_path, char* out_path, size_t out_sz) {
    size_t len = strlen(in_path);
    if (len > 4 && strcmp(in_path + len - 4, ".zst") == 0) {
        snprintf(out_path, out_sz, "%.*s", (int)(len - 4), in_path);
        return 0;
    }
    if (len > 5 && strcmp(in_path + len - 5, ".tzst") == 0) {
        snprintf(out_path, out_sz, "%.*s.tar", (int)(len - 5), in_path);
        return 0;
    }
    if (len > 3 && strcmp(in_path + len - 3, ".gz") == 0) {
        snprintf(out_path, out_sz, "%.*s", (int)(len - 3), in_path);
        return 0;
    }
    if (len > 4 && strcmp(in_path + len - 4, ".tgz") == 0) {
        snprintf(out_path, out_sz, "%.*s.tar", (int)(len - 4), in_path);
        return 0;
    }
    if (len > 3 && strcmp(in_path + len - 3, ".xz") == 0) {
        snprintf(out_path, out_sz, "%.*s", (int)(len - 3), in_path);
        return 0;
    }
    if (len > 4 && strcmp(in_path + len - 4, ".txz") == 0) {
