{"command":"cat << 'EOF' > src/decompress.c
#include "zstd_cli.h"
#include <zlib.h>
#include <lzma.h>

static int decompress_file_zstd(Options* opts, FILE* fin, FILE* fout, uint64_t* out_bytes_out) {
    ZSTD_DCtx* dctx = ZSTD_createDCtx();
    if (!dctx) return 1;

    if (opts->dict_file) {
        FILE* fdict = fopen(opts->dict_file, "rb");
        if (fdict) {
            fseek(fdict, 0, SEEK_END);
            long dsize = ftell(fdict);
            fseek(fdict, 0, SEEK_SET);
            if (dsize > 0) {
                void* dbuf = malloc(dsize);
                if (dbuf && fread(dbuf, 1, dsize, fdict) == (size_t)dsize) {
                    ZSTD_DCtx_loadDictionary(dctx, dbuf, dsize);
                }
                free(dbuf);
            }
            fclose(fdict);
        }
    }

    size_t in_buf_size = 128 * 1024;
    size_t out_buf_size = 128 * 1024;
    void* in_buf = malloc(in_buf_size);
    void* out_buf = malloc(out_buf_size);

    uint64_t total_out = 0;
    int error = 0;

    for (;;) {
        size_t read_bytes = fread(in_buf, 1, in_buf_size, fin);
        if (read_bytes == 0) break;

        ZSTD_inBuffer input = { in_buf, read_bytes, 0 };
        while (input.pos < input.size) {
            ZSTD_outBuffer output = { out_buf, out_buf_size, 0 };
            size_t ret = ZSTD_decompressStream(dctx, &output, &input);
            if (ZSTD_isError(ret)) {
                if (opts->num_inputs == 1 && opts->dict_file == NULL) {
                    fprintf(stderr, "%s\n", ZSTD_getErrorName(ret));
                }
                error = 1;
                break;
            }
            if (output.pos > 0) {
                fwrite(out_buf, 1, output.pos, fout);
                total_out += output.pos;
            }
        }
        if (error) break;
    }

    free(in_buf);
    free(out_buf);
    ZSTD_freeDCtx(dctx);

    *out_bytes_out = total_out;
    return error;
}

static int decompress_file_gzip(FILE* fin, FILE* fout, uint64_t* out_bytes_out) {
    z_stream strm = {0};
    if (inflateInit2(&strm, 15 + 32) != Z_OK) return 1;

    unsigned char in_buf[64 * 1024];
    unsigned char out_buf[64 * 1024];

    uint64_t total_out = 0;
    int error = 0;

    for (;;) {
        size_t read_bytes = fread(in_buf, 1, sizeof(in_buf), fin);
        if (read_bytes == 0) break;

        strm.next_in = in_buf;
        strm.avail_in = read_bytes;

        do {
            strm.next_out = out_buf;
            strm.avail_out = sizeof(out_buf);
            int ret = inflate(&strm, Z_NO_FLUSH);
            if (ret != Z_OK && ret != Z_STREAM_END) {
                error = 1;
                break;
            }
            size_t have = sizeof(out_buf) - strm.avail_out;
            if (have > 0) {
                fwrite(out_buf, 1, have, fout);
                total_out += have;
            }
            if (ret == Z_STREAM_END) break;
        } while (strm.avail_out == 0);

        if (error) break;
    }

    inflateEnd(&strm);
    *out_bytes_out = total_out;
    return error;
}

static int decompress_file_xz(FILE* fin, FILE* fout, uint64_t* out_bytes_out) {
    lzma_stream strm = LZMA_STREAM_INIT;
    if (lzma_auto_decoder(&strm, UINT64_MAX, 0) != LZMA_OK) return 1;

    uint8_t in_buf[64 * 1024];
    uint8_t out_buf[64 * 1024];

    uint64_t total_out = 0;
    int error = 0;

    for (;;) {
        size_t read_bytes = fread(in_buf, 1, sizeof(in_buf), fin);
        if (read_bytes == 0) break;

        strm.next_in = in_buf;
        strm.avail_in = read_bytes;

        do {
            strm.next_out = out_buf;
            strm.avail_out = sizeof(out_buf);
            lzma_ret ret = lzma_code(&strm, LZMA_RUN);
            if (ret != LZMA_OK && ret != LZMA_STREAM_END) {
                error = 1;
                break;
            }
            size_t have = sizeof(out_buf) - strm.avail_out;
            if (have > 0) {
                fwrite(out_buf, 1, have, fout);
                total_out += have;
            }
            if (ret == LZMA_STREAM_END) break;
        } while (strm.avail_out == 0);

        if (error) break;
    }

    lzma_end(&strm);
    *out_bytes_out = total_out;
    return error;
}

static int pass_through_stream(FILE* fin, FILE* fout, uint64_t* out_bytes_out) {
    char buf[64 * 1024];
    uint64_t total = 0;
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), fin)) > 0) {
        fwrite(buf, 1, n, fout);
        total += n;
    }
    *out_bytes_out = total;
    return 0;
}

static int derive_decompressed_filename(const char* in_path, char* out_path, size_t out_sz) {
    size_t len = strlen(in_path);
    if (len > 4 && strcmp(in_path + len - 4, ".zst") == 0) {
        snprintf(out_path, out_sz, "%.*s", (int)(len - 4), in_path);
        return 0;
    }
    if (len > 5 && strcmp(in_path + len - 5, ".tzst") == 0) {
        snprintf(out_path, out_sz, "%.*s.tar", (int)(len - 5), in_path);
        return 0;
    }
    if (len > 3 && strcmp(in_path + len - 3, ".gz") == 0) {
        snprintf(out_path, out_sz, "%.*s", (int)(len - 3), in_path);
        return 0;
    }
    if (len > 4 && strcmp(in_path + len - 4, ".tgz") == 0) {
        snprintf(out_path, out_sz, "%.*s.tar", (int)(len - 4), in_path);
        return 0;
    }
    if (len > 3 && strcmp(in_path + len - 3, ".xz") == 0) {
        snprintf(out_path, out_sz, "%.*s", (int)(len - 3), in_path);
        return 0;
    }
    if (len > 4 && strcmp(in_path + len - 4, ".txz") == 0) {
        snprintf(out_path, out_sz, "%.*s.tar", (int)(len - 4), in_path);
        return 0;
    }
    if (len > 5 && strcmp(in_path + len - 5, ".lzma") == 0) {
        snprintf(out_path, out_sz, "%.*s", (int)(len - 5), in_path);
        return 0;
    }
    return -1;
}

int process_decompress(Options* opts) {
    if (opts->num_inputs == 0) {
        add_input_file(opts, "-");
    }

    /* Check output to stdout console */
    int writing_to_stdout = opts->stdout_mode ||
