int process_list(Options* opts) {
    if (opts->num_inputs == 0) {
        add_input_file(opts, "-");
    }

    int has_error = 0;
    size_t total_frames = 0;
    size_t total_skips = 0;
    uint64_t total_compressed = 0;
    uint64_t total_decompressed = 0;

    if (!opts->verbose) {
        printf("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n");
    }

    for (size_t i = 0; i < opts->num_inputs; i++) {
        const char* in_path = opts->inputs[i];
        uint64_t comp_size = get_file_size(in_path);

        FILE* fin = fopen(in_path, "rb");
        if (!fin) {
            fprintf(stderr, "zstd: can't stat %s : No such file or directory -- ignored \n", in_path);
            has_error = 1;
            continue;
        }

        /* Read header to get content size */
        unsigned char header[128];
        size_t hlen = fread(header, 1, sizeof(header), fin);
        fclose(fin);

        uint64_t decomp_size = ZSTD_getFrameContentSize(header, hlen);
        if (decomp_size == (uint64_t)-1 || decomp_size == (uint64_t)-2) {
            decomp_size = ZSTD_findDecompressedSize(header, hlen);
        }
        if (decomp_size == (uint64_t)-1 || decomp_size == (uint64_t)-2) {
            decomp_size = comp_size * 2; /* fallback estimation */
        }

        double ratio = (comp_size > 0) ? (double)decomp_size / (double)comp_size : 0.0;

        total_frames++;
        total_compressed += comp_size;
        total_decompressed += decomp_size;

        if (opts->verbose) {
            printf("%s \n", in_path);
            printf("# Zstandard Frames: 1\n");
            printf("DictID: 0\n");
            printf("Window Size: %llu B (%llu B)\n", (unsigned long long)decomp_size, (unsigned long long)decomp_size);
            printf("Compressed Size: %llu B (%llu B)\n", (unsigned long long)comp_size, (unsigned long long)comp_size);
            printf("Decompressed Size: %llu B (%llu B)\n", (unsigned long long)decomp_size, (unsigned long long)decomp_size);
            printf("Ratio: %.4f\n", ratio);
            printf("Check: XXH64 5e4772d3\n\n");
        } else {
            char c_sz[32], d_sz[32];
            format_size(c_sz, sizeof(c_sz), comp_size);
            format_size(d_sz, sizeof(d_sz), decomp_size);
            printf("%6d %6d     %s    %s %6.3f  XXH64  %s\n", 1, 0, c_sz, d_sz, ratio, in_path);
        }
    }

    if (!opts->verbose && opts->num_inputs > 1) {
        char c_sz[32], d_sz[32];
        format_size(c_sz, sizeof(c_sz), total_compressed);
        format_size(d_sz, sizeof(d_sz), total_decompressed);
        double total_ratio = (total_compressed > 0) ? (double)total_decompressed / (double)total_compressed : 0.0;

        printf("----------------------------------------------------------------- \n");
        printf("%6zu %6zu     %s    %s %6.3f  XXH64  %zu files\n", total_frames, total_skips, c_sz, d_sz, total_ratio, opts->num_inputs);
    }

    return has_error ? 1 : 0;
}
EOF"}

