{"command":"cat << 'EOF' > src/train.c
#include "zstd_cli.h"

int process_train(Options* opts) {
    if (opts->num_inputs == 0) {
        fprintf(stderr, "Error : no training files provided \n");
        return 1;
    }

    size_t total_samples_bytes = 0;
    size_t nb_samples = opts->num_inputs;
    size_t* samples_sizes = malloc(nb_samples * sizeof(size_t));

    for (size_t i = 0; i < nb_samples; i++) {
        uint64_t sz = get_file_size(opts->inputs[i]);
        samples_sizes[i] = (size_t)sz;
        total_samples_bytes += (size_t)sz;
    }

    if (total_samples_bytes == 0) {
        fprintf(stderr, "!  Warning : nb of samples too low for proper processing !\n"
                        "!  Please provide _one file per sample_.\n"
                        "!  Alternatively, split file(s) into fixed-size samples, with --split=#\n"
                        "Error 14 : nb of samples too low \n");
        free(samples_sizes);
        return 14;
    }

    void* samples_buf = malloc(total_samples_bytes);
    size_t offset = 0;
    for (size_t i = 0; i < nb_samples; i++) {
        FILE* f = fopen(opts->inputs[i], "rb");
        if (f) {
            size_t n = fread((char*)samples_buf + offset, 1, samples_sizes[i], f);
            (void)n;
            fclose(f);
        }
        offset += samples_sizes[i];
    }

    size_t max_dict_sz = opts->max_dict_size ? opts->max_dict_size : 112640;
    void* dict_buf = malloc(max_dict_sz);

    if (total_samples_bytes < max_dict_sz * 10) {
        fprintf(stderr, "!  Warning : data size of samples too small for target dictionary size \n"
                        "!  Samples should be about 100x larger than target dictionary size \n");
    }

    size_t dict_size = ZDICT_trainFromBuffer(dict_buf, max_dict_sz, samples_buf, samples_sizes, (unsigned)nb_samples);

    free(samples_buf);
    free(samples_sizes);

    if (ZSTD_isError(dict_size)) {
        fprintf(stderr, "Error 14 : nb of samples too low \n");
        free(dict_buf);
        return 14;
    }

    const char* dict_out = opts->output_file ? opts->output_file : "dictionary";
    FILE* fd = fopen(dict_out, "wb");
    if (!fd) {
        fprintf(stderr, "zstd: %s: %s \n", dict_out, strerror(errno));
        free(dict_buf);
        return 1;
    }

    fwrite(dict_buf, 1, dict_size, fd);
    fclose(fd);
    free(dict_buf);

    fprintf(stderr, "Save dictionary of size %zu into file %s \n\n", dict_size, dict_out);
    return 0;
}
EOF

cat << 'EOF' > src/benchmark.c
#include "zstd_cli.h"

int process_benchmark(Options* opts) {
    if (opts->num_inputs == 0) {
        fprintf(stderr, "Error: no input file for benchmark\n");
        return 1;
    }

    for (size_t i = 0; i < opts->num_inputs; i++) {
        const char* filename = opts->inputs[i];
        printf("Loading %s...       \n\n\n", filename);

        uint64_t src_sz = get_file_size(filename);
        FILE* f = fopen(filename, "rb");
        if (!f) {
            fprintf(stderr, "zstd: can't stat %s : No such file or directory -- ignored \n", filename);
            continue;
        }

        void* src_buf = malloc(src_sz ? src_sz : 1);
        if (src_sz > 0) {
            size_t n = fread(src_buf, 1, src_sz, f);
            (void)n;
        }
        fclose(f);

        size_t max_dst = src_sz + 1024 + src_sz / 8;
        void* dst_buf = malloc(max_dst);

        int level = opts->bench_level_start ? opts->bench_level_start : 3;

        ZSTD_CCtx* cctx = ZSTD_createCCtx();
        ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, level);

        ZSTD_inBuffer in = { src_buf, src_sz, 0 };
        ZSTD_outBuffer out = { dst_buf, max_dst, 0 };

        clock_t t0 = clock();
        ZSTD_compressStream2(cctx, &out, &in, ZSTD_e_end);
        clock_t t1 = clock();

        double elapsed_c = (double)(t1 - t0) / CLOCKS_PER_SEC;
        if (elapsed_c <= 0.0001) elapsed_c = 0.0001;

        double mb_s_c = ((double)src_sz / (1024.0 * 1024.0)) / elapsed_c;

        ZSTD_DCtx* dctx = ZSTD_createDCtx();
        void* dec_buf = malloc(src_sz ? src_sz : 1);
        ZSTD_inBuffer din = { dst_buf, out.pos, 0 };
        ZSTD_outBuffer dout = { dec_buf, src_sz, 0 };

        t0 = clock();
        ZSTD_decompressStream(dctx, &dout, &din);
        t1 = clock();

        double elapsed_d = (double)(t1 - t0) / CLOCKS_PER_SEC;
        if (elapsed_d <= 0.0001) elapsed_d = 0.0001;

        double mb_s_d = ((double)src_sz / (1024.0 * 1024.0)) / elapsed_d;

        double ratio = (out.pos > 0) ? (double)src_sz / (double)out.pos : 1.0;

        printf(" |-%-16s:  %8llu -> %9zu (x%.1f), %.1f MB/s, %.1f MB/s\n",
               path_basename(filename), (unsigned long long)src_sz, out.pos, ratio, mb_s_c, mb_s_d);

        ZSTD_freeCCtx(cctx);
        ZSTD_freeDCtx(dctx);
        free(src_buf);
        free(dst_buf);
        free(dec_buf);
    }

    return 0;
}
EOF"}

